{
  "nl": {
    "issue": [
      {
        "text": "不动产登记机构应当履行哪些法定职责；申请登记的不动产情况需要进一步证明时如何处理",
        "rules": ["c212-1", "c212-2", "c212-3", "c212-4", "c212-supp"]
      },
      {
        "text": "权利人、利害关系人能否查询、复制不动产登记资料，登记机构负有何种提供义务，利害关系人负有何种保密义务",
        "rules": ["c218-1", "c218-2", "c219-1"]
      },
      {
        "text": "更正登记的申请条件与登记机构的更正义务；异议登记的申请条件、失效事由及异议登记不当的赔偿责任",
        "rules": ["c220-1", "c220-2", "c220-3", "c220-4", "c220-5", "c220-doc"]
      },
      {
        "text": "预告登记的申请条件、对处分的限制效力及预告登记的失效事由",
        "rules": ["c221-1", "c221-2", "c221-3"]
      },
      {
        "text": "提供虚假材料申请登记与因登记错误致人损害的责任承担，以及登记机构赔偿后的追偿",
        "rules": ["c222-1", "c222-2", "c222-3"]
      }
    ],
    "conditions": [
      {
        "text": "申请人已就某不动产向登记机构提出登记申请",
        "rules": ["c212-1", "c212-2", "c212-3", "c212-4", "c212-supp"]
      },
      {
        "text": "申请登记的不动产的有关情况需要进一步证明",
        "rules": ["c212-supp"]
      },
      {
        "text": "申请人为不动产的权利人或利害关系人",
        "rules": ["c218-1", "c218-2", "c220-1"]
      },
      {
        "text": "权利人、利害关系人认为不动产登记簿记载的事项错误并申请更正登记",
        "rules": ["c220-1", "c220-2"]
      },
      {
        "text": "登记簿记载的权利人书面同意更正，或有证据证明登记确有错误",
        "rules": ["c220-2"]
      },
      {
        "text": "登记簿记载的权利人不同意更正，利害关系人申请异议登记",
        "rules": ["c220-3"]
      },
      {
        "text": "当事人签订买卖房屋的协议或其他不动产物权的协议，为保障将来实现物权，并按照约定申请",
        "rules": ["c221-1"]
      },
      {
        "text": "已办理预告登记，他人未经预告登记权利人同意处分该不动产",
        "rules": ["c221-2"]
      },
      {
        "text": "债权消灭，或自能够进行不动产登记之日起九十日内未申请登记",
        "rules": ["c221-3"]
      },
      {
        "text": "当事人提供虚假材料申请登记并造成他人损害",
        "rules": ["c222-1"]
      },
      {
        "text": "因登记错误造成他人损害",
        "rules": ["c222-2"]
      },
      {
        "text": "登记机构已赔偿，且存在造成登记错误的人",
        "rules": ["c222-3"]
      }
    ],
    "exceptions": [
      {
        "text": "未经预告登记的权利人同意处分该不动产的，不发生物权效力（对不动产物权变动登记生效的例外）",
        "rules": ["c221-2"]
      },
      {
        "text": "申请人自异议登记之日起十五日内不提起诉讼的，异议登记失效",
        "rules": ["c220-4"]
      },
      {
        "text": "债权消灭或自能够进行不动产登记之日起九十日内未申请登记的，预告登记失效",
        "rules": ["c221-3"]
      }
    ],
    "effects": [
      {
        "text": "登记机构应当查验权属证明和其他必要材料、就有关登记事项询问申请人、如实及时登记有关事项，并履行法律、行政法规规定的其他职责",
        "rules": ["c212-1", "c212-2", "c212-3", "c212-4"]
      },
      {
        "text": "登记机构可以要求申请人补充材料，必要时可以实地查看",
        "rules": ["c212-supp"]
      },
      {
        "text": "权利人或利害关系人可以申请查询、复制不动产登记资料，登记机构应当提供",
        "rules": ["c218-1", "c218-2"]
      },
      {
        "text": "利害关系人不得公开、非法使用权利人的不动产登记资料",
        "rules": ["c219-1"]
      },
      {
        "text": "权利人或利害关系人可以申请更正登记；记载的权利人书面同意或有证据证明登记确有错误的，登记机构应当予以更正",
        "rules": ["c220-1", "c220-2"]
      },
      {
        "text": "记载的权利人不同意更正的，利害关系人可以申请异议登记；异议登记不当造成权利人损害的，权利人可以请求申请人赔偿",
        "rules": ["c220-3", "c220-5"]
      },
      {
        "text": "异议登记使登记簿记载的权利失去正确性推定效力，排除善意取得的适用（学理，非本条明文）",
        "rules": ["c220-doc"]
      },
      {
        "text": "当事人可以申请预告登记；预告登记后未经预告登记权利人同意处分该不动产的，不发生物权效力",
        "rules": ["c221-1", "c221-2"]
      },
      {
        "text": "提供虚假材料申请登记造成他人损害的，应当承担赔偿责任",
        "rules": ["c222-1"]
      },
      {
        "text": "因登记错误造成他人损害的，登记机构应当承担赔偿责任；赔偿后可以向造成登记错误的人追偿",
        "rules": ["c222-2", "c222-3"]
      }
    ],
    "priority": [
      {
        "text": "预告登记后未经预告登记权利人同意的处分不发生物权效力，优先于一般的不动产物权变动登记生效规则",
        "rules": ["c221-2"]
      },
      {
        "text": "登记机构先对外承担赔偿责任，再向造成登记错误的人追偿，实现内部责任分担",
        "rules": ["c222-2", "c222-3"]
      }
    ],
    "distinguish": [
      {
        "text": "笔记中的首次登记、变更登记、转移登记、注销登记，以及“未办理首次登记不得办理其他类型登记”，出自《不动产登记暂行条例》，本条未规定",
        "rules": []
      },
      {
        "text": "不动产登记簿与权属证书记载不一致时以登记簿为准（第217条），不在本条范围内",
        "rules": []
      },
      {
        "text": "异议登记期间登记机构应书面告知申请人有关事项、申请人可自担风险继续办理，属《不动产登记暂行条例》及司法解释内容，本条未规定",
        "rules": []
      },
      {
        "text": "LEGO 卡片所列“土地承包经营权互换、转让或地役权设立未经登记不得对抗善意第三人”属登记对抗主义（第335、374条），与本条的登记生效主义不同",
        "rules": []
      },
      {
        "text": "第212条是登记机构职责的程序性规定，本身不直接产生物权变动效果",
        "rules": []
      }
    ]
  },
